INSERT INTO profile (id, first_name, last_name, full_name, role, tagline, intro, summary, location, email, availability, current_company, portrait_key, portrait_cutout_key, about_image_key, about_image_caption, og_image_key, resume_key) VALUES (1, 'Raden', 'Issa', 'Raden Mochamad Issa Wirakusumah', 'Product & Project Manager', 'Driving projects, products & growth.', 'Bridging business needs and engineering teams. Shipping ahead of schedule.', 'I''m a Product & Project Manager with a technical background in software development, currently managing several digital products at once. I write the backlog tickets, prioritize the work, monitor delivery and keep stakeholders aligned. With hands-on engineering experience, I understand system requirements well enough to bridge business needs and the development team.', 'Jakarta, Indonesia', 'rdnsa123@gmail.com', 'Have a product to ship or a team to lead? Let''s talk.', 'PT InfantAI Teknologi Nusantara', 'profile/portrait.webp', 'profile/portrait-cutout.webp', 'about/itb-gig-economy.webp', 'Aula Timur ITB, Bandung — launch of Pelatihan GIG Economy & the AI Open Innovation Challenge, January 2026.', 'og/cover.jpg', NULL);
