INSERT INTO publications (title, authors, venue, details, year, url, pdf_url, citations, summary, sort) VALUES ('Predicting the Growth of MSMEs in West Java Towards Golden Indonesia 2045 Using Linear Regression', '["Raden Mochamad Issa Wirakusumah","Rizki Hesananda"]', 'Innotech: Jurnal Ilmu Komputer, Sistem Informasi dan Teknologi Informasi', '2 (1)', '2025', 'https://ejournal.cyber-univ.ac.id/index.php/innotech/article/view/87', 'https://ejournal.cyber-univ.ac.id/index.php/innotech/article/download/87/118', 1, 'Projects the number of MSMEs in West Java up to 2045 with a linear regression model trained on West Java open data, in line with the Golden Indonesia 2045 vision.', 0);
INSERT INTO publications (title, authors, venue, details, year, url, pdf_url, citations, summary, sort) VALUES ('Implementing Private Cloud Storage with ownCloud and Ubuntu Linux on Oracle VirtualBox', '["Dedi Dwi Saputra","Diah Dwi Noviati","Raden Mochamad Issa Wirakusumah","Achmad Faiz","Fildzah Dwifadzila Wijaya","Mohammad Fauzan Zidny"]', 'Jurnal Komputer Antartika', '2 (1), 9–15', '2024', 'https://ejournal.mediaantartika.id/index.php/jka/article/view/232', 'https://ejournal.mediaantartika.id/index.php/jka/article/download/232/51', 3, 'Evaluates ownCloud on Ubuntu, virtualised in VirtualBox, as a secure and flexible private cloud for storing coursework and exams, measuring its security and performance.', 1);
