INSERT INTO moments (image_key, alt, caption, sort) VALUES ('moments/pari-team.webp', 'Raden Issa with ten teammates from PT Super Pasar Rakyat Indonesia posing arm in arm in the office', 'With the team at PT Super Pasar Rakyat Indonesia (PARI), BRI Group.', 9);
INSERT INTO translations (locale, data) VALUES ('id', '{"profile":{"tagline":"Menggerakkan proyek, produk & pertumbuhan.","intro":"Menjembatani kebutuhan bisnis dan tim engineering. Selesai lebih cepat dari jadwal.","summary":"Saya Product & Project Manager dengan latar belakang teknis di pengembangan software, dan saat ini mengelola beberapa produk digital sekaligus. Saya menulis tiket backlog, memprioritaskan pekerjaan, memantau delivery, dan menjaga keselarasan stakeholder. Dengan pengalaman langsung di engineering, saya cukup memahami kebutuhan sistem untuk menjembatani kebutuhan bisnis dan tim pengembang.","location":"Jakarta, Indonesia","availability":"Punya produk untuk diluncurkan atau tim untuk dipimpin? Mari bicara.","aboutImageCaption":"Aula Timur ITB, Bandung — peluncuran Pelatihan GIG Economy & AI Open Innovation Challenge, Januari 2026."},"stats":[{"label":"Impresi pencarian organik","detail":"IFC News, berawal dari nol trafik organik"},{"label":"Biaya operasional bulanan","detail":"$150 → $50/bulan lewat migrasi VPS & optimasi token LLM"},{"label":"Engineer & profesional IT dipimpin","detail":"Frontend, backend, QA, BA, UI/UX, marketing, IT support"},{"value":"~3 mgg","label":"Lebih cepat dari jadwal","detail":"Refactor database Satglow ERP"},{"value":"~5 hari","label":"Go-live lebih awal, tanpa kendala","detail":"NordPartners, selesai lebih cepat tanpa masalah implementasi"},{"label":"IPK — Lulusan Terbaik","detail":"Terbaik di angkatan Teknologi Informasi, dengan beasiswa penuh"}],"skills":[{"title":"Manajemen Proyek"},{"title":"Manajemen Produk"},{"title":"Pertumbuhan Bisnis","items":["Strategi SEO","Product Pitching","Perencanaan Marketing","Kolaborasi Lintas Fungsi"]},{"title":"Perangkat"}],"projects":[{"slug":"ifc-news","category":"AI · Media fintech","tagline":"Platform berita keuangan & investasi berbasis AI.","summary":"Platform keuangan berbasis AI yang menjembatani data pasar yang kompleks dengan wawasan investasi yang bisa langsung ditindaklanjuti bagi investor pemula.","description":"Platform keuangan digital yang membantu pengguna menemukan, memahami, dan menganalisis informasi pasar keuangan melalui berita, wawasan pasar, dan fitur berbasis AI.","roleDetail":"Membangun proses pengembangan dan roadmap produk, lalu menggerakkan tuas pertumbuhan — SEO, biaya infrastruktur, pembayaran, dan paket freemium.","coverAlt":"Beranda IFC News: pasar Indonesia, diurai oleh AI","metrics":[{"label":"Total impresi"},{"label":"Total klik"},{"label":"Puncak impresi harian"},{"label":"Puncak klik harian"}],"modules":[{"title":"Berita Keuangan","body":"Berita pasar Indonesia dengan terjemahan real-time ke bahasa pembaca."},{"title":"Wawasan Berbasis AI","body":"Ringkasan dan sentimen AI di setiap berita, lengkap dengan pendapatan, laba bersih, dan kapitalisasi pasar."},{"title":"Rekomendasi Saham & Analisis Mingguan","body":"Satu pilihan saham harian dengan target harga dan stop-loss, ditambah sentimen pasar dan analisis mingguan."},{"title":"Minat yang Dipersonalisasi","body":"Feed yang disesuaikan dengan minat keuangan setiap pembaca."}],"stories":[{"title":"Proses & pertumbuhan organik","challenge":["Belum ada **SDLC** yang terstruktur.","Pengembangan dilakukan berdasarkan kebutuhan mendesak, **tanpa proses, perencanaan, atau sistem yang terstandar**.","**Trafik organik masih nol.**"],"responsibilities":["Membangun **proses pengembangan** yang terstruktur.","Meningkatkan **performa SEO** dalam waktu kurang dari 1 bulan.","Menyusun **roadmap** produk."],"initiatives":["Menerapkan **Scrum & Sprint Planning**.","Mengelola **Backlog & Roadmap**.","Mengoptimalkan **fondasi SEO**.","Mempresentasikan dan mem-pitch **IFCNews** di ITB."],"impact":["**SEO** selesai **~20 hari lebih cepat dari jadwal**.","**Scrum** menjadi proses kerja standar tim.","**Roadmap Premium Subscription** tersusun untuk 4 sprint ke depan."]},{"title":"Efisiensi biaya & monetisasi","challenge":["**Biaya operasional tinggi** karena ketergantungan pada hosting Railway.","**Belum ada integrasi payment gateway** untuk transaksi langsung pengguna.","**Belum ada skema freemium** untuk mendukung strategi marketing dan akuisisi pengguna."],"responsibilities":["**Menekan biaya** dan meningkatkan efisiensi operasional platform.","Memimpin **implementasi payment gateway** untuk transaksi pengguna.","**Menyelaraskan skema freemium** dengan target akuisisi marketing."],"initiatives":["**Memigrasikan server** dari Railway ke **VPS mandiri**.","**Mengurangi beban server** untuk menekan biaya operasional bulanan.","Mengimplementasikan **payment gateway** melalui Pakasir dan Saweria.","Meluncurkan **model freemium** untuk mempercepat akuisisi pengguna."],"impact":["**Efisiensi biaya ~66%** — biaya operasional turun dari $150 ke $50/bulan lewat pengelolaan resource yang terkendali.","Integrasi **payment gateway yang aman** untuk mendukung transaksi dan pendapatan berulang.","Mempercepat akuisisi pengguna baru dan konversi marketing melalui akses fitur dasar (**Model Freemium**)."]}],"gallery":[{"src":"projects/ifc-news/news-stream.webp","alt":"News stream IFC News dengan ringkasan dan sentimen AI","caption":"News Stream — ringkasan AI, sentimen, dan data fundamental di setiap berita."},{"src":"projects/ifc-news/search-console.webp","alt":"Grafik performa Google Search Console untuk ifcnews.id","caption":"Google Search Console, tampilan 3 bulan (Juni 2026)."},{"src":"projects/ifc-news/sprint-board.webp","alt":"Papan pengembangan IFC News di GitHub Projects","caption":"Sprint board di GitHub Projects."},{"src":"projects/ifc-news/team.webp","alt":"Tim IFC News dalam sesi kerja","caption":"Sesi kerja bersama tim IFC News."}]},{"slug":"satglow-erp","category":"ERP · Operasional","tagline":"Sistem manajemen gudang & operasional.","summary":"Solusi ERP terintegrasi untuk memusatkan inventaris multi-gudang, merapikan work order operasional, dan mengotomatiskan pemotongan stok real-time di setiap transaksi event.","description":"Sistem ERP terpusat untuk Satellite of Glow yang mengelola inventaris di banyak gudang, work order, pergerakan stok, dan transaksi kasir event.","roleDetail":"Memimpin implementasi ERP — proses pengembangan yang fleksibel, kebutuhan pengguna yang tervalidasi, dan roadmap produk.","coverAlt":"Dashboard gudang Satglow ERP","modules":[{"title":"Inventaris Multi-Gudang","body":"Satu inventaris untuk semua gudang, lengkap dengan vendor dan transfer antargudang."},{"title":"Work Order","body":"Membuat dan melacak work order operasional."},{"title":"Pergerakan Stok","body":"Melacak pergerakan stok dan level inventaris, hingga pemindaian barcode dan checkout."},{"title":"Kasir Event","body":"Transaksi kasir dengan sinkronisasi stok real-time dan struk otomatis."}],"stories":[{"title":"Dibangun dari nol","challenge":["Sistem **dikembangkan dari nol**.","**Kebutuhan** berubah mengikuti kebutuhan pengguna.","Belum ada **siklus pengembangan** yang mapan."],"responsibilities":["Membangun **proses pengembangan** yang fleksibel.","Memastikan **kebutuhan pengguna** tervalidasi.","Menyusun **roadmap produk**."],"initiatives":["**Metode RAD**: Requirement Planning, User Design, Construction secara iteratif.","**Roadmap**: Division Master, Excel Engine, Batch Inventory, Expired Batching."],"impact":["**Refactor DB** selesai **~3 minggu lebih cepat dari jadwal**.","**Siklus pengembangan** menjadi lebih terstruktur.","**Kebutuhan** menjadi lebih mudah divalidasi."]}]},{"slug":"nordpartners","category":"PropTech · Kemitraan","tagline":"Platform kemitraan properti Melbourne.","summary":"Platform kemitraan digital yang menghubungkan investor dengan peluang properti di Melbourne, merapikan seluruh alur dari onboarding pengguna dan persetujuan admin hingga akses event terverifikasi QR.","description":"NordPartners adalah platform digital untuk mendukung kegiatan kemitraan properti di Melbourne, menghubungkan peserta dengan peluang properti serta mengelola proses registrasi dan persetujuan.","roleDetail":"Mengelola kebutuhan, prioritas, koordinasi stakeholder, dan delivery pengembangan.","coverAlt":"Beranda NordPartners: akses strategis ke peluang properti dan investasi di Australia","metrics":[{"value":"~5 hari","label":"Selesai lebih cepat dari jadwal"},{"label":"Kendala implementasi saat go-live"}],"modules":[{"title":"Peluang Properti & Registrasi","body":"Menampilkan peluang properti Melbourne kepada peserta. Mengelola registrasi dan alur partisipasi pengguna dari pendaftaran awal hingga onboarding."},{"title":"Verifikasi & Persetujuan Admin","body":"Verifikasi email untuk pengguna terdaftar memastikan keaslian. Admin meninjau dan menyetujui peserta sebelum memberi akses ke event properti."},{"title":"Manajemen Akses Event","body":"Sistem akses berbasis QR untuk peserta yang disetujui di event properti. Mempercepat proses masuk dan memastikan hanya pengguna terverifikasi yang mendapat akses."}],"flows":[{"title":"Nilai utama","steps":["Peluang properti","Registrasi","Verifikasi","Persetujuan","Event"]}],"stories":[{"title":"Tetap rilis saat kebutuhan terus berubah","challenge":["**Kebutuhan** berkembang mengikuti **kebutuhan stakeholder**."],"responsibilities":["Memastikan delivery tetap selaras dengan **target** dan **ekspektasi stakeholder**."],"initiatives":["Menggunakan metodologi **RAD**.","Mengelola **kebutuhan** dan **prioritas** pengembangan.","**Mengoordinasikan** delivery modul KCL × NØRD.","Menyusun **roadmap pemantauan konversi**."],"impact":["Delivery selesai sekitar **5 hari lebih cepat dari jadwal**.","**Nol kendala implementasi** saat go-live."]}]},{"slug":"nose-one","category":"ERP · HRIS","tagline":"Platform manajemen pabrik terintegrasi — NOSE HRIS.","summary":"Modul HRIS terpusat di dalam platform ERP pabrik yang menyatukan data karyawan, shift kehadiran yang kompleks, penggajian, dan rekrutmen dalam satu pusat operasional.","description":"NOSE ONE adalah sistem terintegrasi yang menghubungkan berbagai divisi pabrik dalam satu platform terpusat. Saya mengelola lingkup HRIS, dengan fokus pada manajemen karyawan, kehadiran, penggajian, dan operasional talenta.","roleDetail":"Mengelola kebutuhan HRIS, prioritas, desain alur kerja, koordinasi stakeholder & delivery.","coverAlt":"Dashboard NOSE ONE HRIS","modules":[{"title":"Karyawan","body":"Data karyawan, organisasi, dan tenaga kerja."},{"title":"Kehadiran","body":"Shift, lembur, cuti, dan kepatuhan."},{"title":"Penggajian","body":"Manajemen penggajian."},{"title":"Talenta","body":"Rekrutmen dan onboarding."}],"flows":[{"title":"Nilai utama","steps":["Satu sistem","Data HR terpusat","Operasional HR terintegrasi","Visibilitas manajemen lebih baik"]}]},{"slug":"aix-expo","category":"Event · AI","tagline":"Platform summit & pameran AI.","summary":"Platform event dan pameran terintegrasi yang menghubungkan perusahaan teknologi global, profesional industri, dan pengunjung melalui showcase AI, summit, dan business matchmaking.","description":"AIX Expo adalah platform digital untuk summit dan pameran bertema AI, yang menghubungkan perusahaan teknologi, pelaku bisnis, profesional, kreator, dan pengunjung dalam satu pengalaman event terintegrasi.","roleDetail":"Mengelola kebutuhan proyek, prioritas, koordinasi stakeholder, dan delivery pengembangan.","coverAlt":"Beranda AIX Indonesia: AI Summit utama di Indonesia","modules":[{"title":"Pameran AI","body":"Menampilkan teknologi dan solusi AI."},{"title":"Summit","body":"Mendukung diskusi dan sesi bertema AI."},{"title":"Koneksi Bisnis","body":"Menghubungkan perusahaan dengan calon mitra."},{"title":"Pengalaman Pengunjung","body":"Menyediakan informasi dan akses ke event."}],"flows":[{"title":"Ekosistem","steps":["Perusahaan teknologi","AIX Expo","Bisnis & profesional","Pengunjung"]},{"title":"Nilai utama","steps":["Teknologi AI","Pameran","Koneksi","Pengalaman"]}]},{"slug":"genius-ai","category":"Hardware AI · EdTech","tagline":"Teman bicara yang membantu anak belajar bahasa Inggris dan berlatih berbicara.","summary":"Perangkat interaktif berbasis AI yang memadukan hardware ESP32 dengan LLM terbaik, sehingga anak bisa belajar bahasa Inggris dan melatih kemampuan berbicara lewat percakapan yang seru dan alami.","description":"Bagian dari lini pendidikan anak usia dini InfantAI: perangkat pendamping ringkas berbasis ESP32 yang menjalankan XiaoZhi, platform asisten suara AI dari China, dan terhubung ke LLM terbaik. Anak belajar bahasa Inggris dan berlatih berbicara cukup dengan mengobrol bersamanya.","roleDetail":"Salah satu lini produk InfantAI yang saya kelola secara bersamaan.","coverAlt":"Perangkat Genius AI dengan casing dinosaurus hijau dan kelinci merah muda","modules":[{"title":"Hardware ESP32","body":"Perangkat ESP32 yang ringkas dengan layar sendiri, dibalut casing yang lucu."},{"title":"XiaoZhi + LLM terbaik","body":"Menjalankan XiaoZhi, platform asisten suara AI dari China, yang menghubungkan setiap percakapan ke large language model terdepan."},{"title":"Belajar bahasa Inggris & berbicara","body":"Dirancang untuk anak: mereka belajar bahasa Inggris dan makin percaya diri berbicara lewat percakapan sehari-hari."}]},{"slug":"kato-report","category":"AI · Fasilitas kampus","tagline":"Laporan toilet yang langsung sampai ke petugas kebersihan.","summary":"Aplikasi laporan toilet kampus untuk UPI Tasikmalaya: mahasiswa memindai QR di pintu untuk melapor, petugas kebersihan menuntaskan laporan, dan chatbot AI menjawab pertanyaan seputar data.","description":"Aplikasi web untuk Universitas Pendidikan Indonesia Kampus Tasikmalaya. Mahasiswa melaporkan toilet yang kotor atau rusak cukup dengan memindai kode QR di pintunya, tanpa login dan tanpa nama. Laporan langsung sampai ke petugas kebersihan, status setiap laporan terbuka untuk umum, dan pengawas bisa bertanya ke chatbot AI tentang data dengan bahasa sehari-hari.","roleDetail":"Merancang produk untuk tiga peran — mahasiswa, petugas kebersihan, dan pengawas — dari alur pelaporan lewat QR hingga analitik AI.","coverAlt":"Beranda Kato Report: pilih peran sebagai mahasiswa, petugas kebersihan, atau pengawas","modules":[{"title":"Lapor lewat QR, tanpa login","body":"Setiap pintu toilet punya stiker QR yang langsung membuka form laporan untuk toilet tersebut. Peta gedung dan pilihan lantai menjadi cadangan jika stiker hilang atau rusak."},{"title":"Antrean petugas kebersihan","body":"Petugas memilih namanya, melihat laporan yang menunggu beserta prioritas dan kategorinya, lalu mencatat toilet yang sudah dibersihkan."},{"title":"Pelacakan publik & leaderboard","body":"Setiap laporan dan statusnya terbuka untuk siapa saja, bisa difilter berdasarkan status dan prioritas. Leaderboard mengurutkan pelapor berdasarkan laporan yang benar-benar ditindaklanjuti."},{"title":"Chatbot AI atas data","body":"Pengawas bertanya dengan bahasa sehari-hari, misalnya gedung dengan laporan terbanyak atau rata-rata waktu penyelesaian. AI hanya melihat agregat dari database, bukan teks keluhan mentah."}],"flows":[{"title":"Alur laporan","steps":["Pindai QR di pintu","Lapor","Antrean petugas","Dibersihkan & selesai","Status publik"]}],"gallery":[{"src":"projects/kato-report/map.webp","alt":"Peta gedung UPI Tasikmalaya dengan huruf tiap gedung","caption":"Peta gedung dan pilihan lantai, untuk toilet yang stiker QR-nya hilang."},{"src":"projects/kato-report/reports.webp","alt":"Halaman laporan masuk: 3 dari 4 laporan selesai dan kartu laporan prioritas rendah","caption":"Pelacak laporan publik dengan filter status dan prioritas."}]}],"experience":[{"location":"Shenzhen, Guangdong, Tiongkok","start":"Sep 2025","end":"Sekarang","summary":"Startup berbasis AI yang membangun produk digital untuk parenting, pendidikan anak usia dini, dan berita keuangan — Infant.AI, GeniusAI, dan IFCNews.","points":["Memimpin pengembangan software end-to-end — kebutuhan, perencanaan, pengembangan, QA, deployment, dan optimasi pasca-rilis.","Mengelola tim lintas fungsi berisi 10 engineer dan profesional IT di Frontend, Backend, QA, Business Analysis, Marketing, UI/UX, dan IT Support.","Mendefinisikan kebutuhan produk, user story, acceptance criteria, scope, milestone, dan backlog dari kebutuhan bisnis dan kelayakan teknis.","Mengelola roadmap, prioritas, jadwal, resource, risiko, dan komunikasi stakeholder di beberapa proyek yang berjalan bersamaan.","Merencanakan dan mengelola anggaran proyek — mengestimasi biaya, mengalokasikan anggaran untuk infrastruktur, tools, dan resource tim, serta memantau realisasi terhadap rencana.","Menerapkan Role-Based Access Control (RBAC) untuk hak akses per peran.","Memimpin implementasi ERP untuk Satglow Invent — inventaris multi-gudang dan alur kerja operasional.","Memimpin implementasi payment gateway yang mendukung beberapa penyedia.","Memigrasikan infrastruktur dari Railway ke VPS mandiri, termasuk stack dan database, tanpa mengganggu ketersediaan sistem.","Menekan biaya operasional bulanan dari ~$150 ke ~$50 lewat migrasi VPS dan optimasi token API LLM.","Meluncurkan model freemium untuk mendukung marketing, akuisisi, dan konversi pengguna.","Mendorong perbaikan produk berdasarkan masukan pengguna, prioritas bisnis, batasan teknis, dan performa produk.","Menyiapkan pemantauan proyek dan alur kerja pengembangan agar progres terlihat jelas bagi tim engineering dan lintas fungsi."]},{"start":"Mar 2026","end":"Agu 2026","summary":"Perusahaan IT Indonesia yang berfokus pada pengembangan software, integrasi sistem, dan transformasi digital.","points":["Mengelola proyek pengembangan software dari perencanaan hingga deployment.","Berkoordinasi dengan klien untuk mengumpulkan dan mendefinisikan kebutuhan bisnis.","Merencanakan jadwal proyek dan memantau progres agar delivery tepat waktu.","Berkolaborasi dengan developer, QA engineer, UI/UX, dan stakeholder di sepanjang siklus proyek.","Menyiapkan dokumentasi proyek dan memastikan deliverable memenuhi standar kualitas."]},{"location":"Jakarta Pusat","start":"Feb 2025","end":"Okt 2025","summary":"PARI — marketplace digital BRI Group untuk komoditas pertanian, yang mendukung petani, peternak, nelayan, dan pelaku usaha mikro.","points":["Berperan sebagai intern lintas fungsi di product management, koordinasi proyek, full-stack development, dan QA dalam sprint Agile.","Mendukung fitur keuangan — TopUp, Withdrawal, dan Settlement — dengan Laravel, MySQL, Docker, dan Redis.","Mengelola task sprint, timeline, dan komunikasi antara tim produk, desain, dan engineering.","Merancang, menguji, dan mengoptimalkan modul lewat QA terstruktur, tuning performa, dan analisis masukan pengguna."]},{"location":"Jakarta Selatan","start":"Jan 2024","end":"Des 2024","summary":"Inovasi kesehatan mental yang didanai Kemendikbudristek — aplikasi berbasis AI yang memantau kesejahteraan emosional dengan grafologi, pengenalan wajah, dan machine learning.","points":["Memimpin perencanaan roadmap, prioritas fitur, pengelolaan backlog, dan eksekusi sprint dengan Agile Scrum.","Bekerja dengan developer dan desainer UI/UX pada fitur analisis suasana hati berbasis machine learning.","Menjalankan usability testing dengan 50+ pengguna untuk meningkatkan pengalaman produk.","Melacak progres dan kebutuhan di Jira, Confluence, dan Notion.","Mendapatkan pendanaan penuh dari Kemendikbudristek dan pengakuan nasional di bidang teknologi kesehatan mental."]}],"education":[{"degree":"Sarjana Teknologi Informasi (S.Kom)","location":"TB Simatupang, Jakarta Selatan","period":"Sep 2022 — Sep 2026","honor":"Lulusan Terbaik","imageAlt":"Raden Issa di wisuda Universitas Siber Indonesia, mengenakan selempang Lulusan Terbaik dan memegang piagam penghargaan, bersama keluarga","points":["Lulusan Terbaik (Wisudawan Terbaik) program Teknologi Informasi pada Wisuda ke-4 universitas, dengan IPK 3.97.","Beasiswa penuh — 100% biaya kuliah selama empat tahun, atas prestasi akademik dan kepemimpinan.","Juara 1, Cyber Entrepreneur Product Innovation Competition — private cloud berbasis Raspberry Pi dan Nextcloud untuk UMKM dan rumah tangga.","Menerbitkan riset tentang penyimpanan private cloud dengan OwnCloud dan Ubuntu Linux (Google Scholar).","Menerbitkan riset prediksi pertumbuhan UMKM di Jawa Barat dengan regresi linear (Google Scholar).","Merancang sistem pemantauan lingkungan berbasis IoT dengan NodeMCU, sensor gas dan iklim, untuk peringatan bahaya real-time.","Pembicara di Program Kesadaran Keamanan Data untuk 50+ peserta."],"school":"Universitas Siber Indonesia"}],"organizations":[{"role":"Ketua","period":"Jul 2023 — Sekarang","summary":"Memimpin program akademik dan sosial Himpunan Mahasiswa Teknologi Informasi.","points":["Menyelenggarakan kunjungan perusahaan ke XL Axiata dan Allo Bank.","Memimpin pengabdian masyarakat tentang literasi digital dan kesadaran keamanan siber.","Mempererat anggota lewat workshop, proyek internal, dan acara networking."]},{"period":"Agu 2023 — Jan 2024","summary":"Kompetisi desain UI/UX tingkat nasional yang diselenggarakan Universitas Siber Indonesia.","points":["Mengelola infrastruktur IT untuk 100+ peserta dari 10+ universitas.","Menjaga uptime 100% selama presentasi dan penjurian.","Membangun sistem registrasi dan data yang mempercepat verifikasi peserta hingga 40%.","Menyelesaikan kendala on-site maupun remote rata-rata dalam sekitar 5 menit."]}],"moments":[{"src":"moments/itb-stage.webp","alt":"Pemandangan dari meja pembicara di ruang kuliah ITB: mikrofon, laptop berisi slide pelatihan AI, dan mahasiswa di kursi bertingkat","caption":"Dari meja pembicara di ITB, Bandung, saat memandu sesi pelatihan AI."},{"src":"moments/graduation-confetti.webp","alt":"Raden Issa di panggung mengenakan toga, memegang piagam penghargaan di bawah hujan confetti","caption":"Menerima penghargaan Lulusan Terbaik pada Wisuda ke-4 Universitas Siber Indonesia."},{"src":"moments/graduation-podium.webp","alt":"Raden Issa di podium di samping bendera Merah Putih saat upacara wisuda","caption":"Di podium saat Wisuda ke-4."},{"src":"moments/video-shoot.webp","alt":"Raden Issa direkam sedang membahas AI di kursi belakang mobil, terlihat melalui monitor kamera","caption":"Di depan kamera, membahas AI serta product & project management dalam sesi syuting video."},{"src":"moments/itb.webp","alt":"Raden Issa dan seorang teman berbaju batik tersenyum di ITB, Bandung, tempat ia menjadi pembicara pelatihan AI","caption":"Di ITB, Bandung, sebagai pembicara pelatihan AI."},{"src":"moments/pari-office.webp","alt":"Raden Issa bersama puluhan rekan di kantor PT Super Pasar Rakyat Indonesia, memegang tas PARI dan balon kuning","caption":"Bersama rekan-rekan di kantor PARI, PT Super Pasar Rakyat Indonesia."},{"src":"moments/team-dinner.webp","alt":"Raden Issa bersama delapan rekan tim PT InfantAI Teknologi Nusantara di meja makan, berpose cakar dengan ceria","caption":"Makan malam bersama tim PT InfantAI Teknologi Nusantara."},{"src":"moments/panel.webp","alt":"Raden Issa berbicara dengan mikrofon di meja panel, dengan papan nama para panelis","caption":"Menjadi panelis sebagai IT Project & Product Manager PT InfantAI Teknologi Nusantara."},{"src":"moments/pari-team.webp","alt":"Raden Issa bersama sepuluh rekan tim PT Super Pasar Rakyat Indonesia berpose saling merangkul di kantor","caption":"Bersama tim PT Super Pasar Rakyat Indonesia (PARI), BRI Group."},{"src":"moments/itb-class.webp","alt":"Raden Issa memberi materi di depan kelas ITB saat sesi pelatihan AI, dengan peserta duduk di meja panjang","caption":"Memandu kelas pelatihan AI di ITB, Bandung."}],"publications":[{"summary":"Memproyeksikan jumlah UMKM di Jawa Barat hingga 2045 dengan model regresi linear berbasis data terbuka Jawa Barat, sejalan dengan visi Indonesia Emas 2045.","title":"Prediksi Pertumbuhan Jumlah UMKM di Jawa Barat Menuju Indonesia Emas 2045 Menggunakan Regresi Linear"},{"summary":"Mengevaluasi ownCloud di Ubuntu yang divirtualisasi dengan VirtualBox sebagai private cloud yang aman dan fleksibel untuk menyimpan tugas dan ujian, mengukur keamanan dan kinerjanya.","title":"Implementasi Private Cloud Storage dengan Menggunakan ownCloud dan Linux Ubuntu pada VirtualBox Oracle"}]}');
